/* HireFlow — static hackathon MVP. No authentication, external mail or AI inference is claimed. */
(()=>{'use strict';
const KEY='hireflow_web_mvp_v2', SESSION='hireflow_admin_demo';
const uid=()=>Math.random().toString(36).slice(2,10)+Date.now().toString(36).slice(-5);
const date=()=>new Date().toISOString();
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=esc;
const formatDate=v=>v?new Date(v).toLocaleDateString('az-AZ',{day:'2-digit',month:'short',year:'numeric'}):'—';
const initials=s=>(s||'H F').split(/\s+/).slice(0,2).map(w=>w.charAt(0)).join('').toUpperCase();
const rand=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
const defaults=()=>{
const jobs=[
{id:'python',title:'Python təlimçisi',company:'ALAS Academy',location:'Bakı · Əyani',type:'Tam ştat',description:'Tələbələrə Python proqramlaşdırma və verilənlər bazaları üzrə praktik dərslər keçmək, tapşırıqlar hazırlamaq və inkişaflarını izləmək üçün təlimçi axtarılır.',responsibilities:'Python dərslərini planlaşdırmaq; praktiki layihələr hazırlamaq; tələbələrə rəy vermək; tədris komandasına hesabat təqdim etmək.',criteria:[{id:'p1',name:'Python',keywords:'python, django, flask, fastapi',required:true},{id:'p2',name:'SQL',keywords:'sql, postgresql, mysql, sqlite, mssql',required:true},{id:'p3',name:'İngilis dili / IELTS',keywords:'ielts, english b2, english c1, ingilis dili b2',required:false},{id:'p4',name:'Bakıda əyani dərs imkanı',keywords:'bakı, baku, onsite baku, əyani',required:false}],github:true,linkedin:true,status:'active',views:rand(160,220),created:date()},
{id:'front',title:'Frontend developer',company:'North Studio',location:'Bakı · Hibrid',type:'Tam ştat',description:'İstifadəçi yönümlü, sürətli və əlçatan veb interfeyslər qurmaq üçün frontend mütəxəssisi axtarırıq.',responsibilities:'Komponent əsaslı interfeyslərin qurulması, komanda ilə kod icmalı, performans və əlçatanlıq optimallaşdırılması.',criteria:[{id:'f1',name:'JavaScript',keywords:'javascript, typescript, js, ts',required:true},{id:'f2',name:'React',keywords:'react, next.js, nextjs',required:true},{id:'f3',name:'CSS və responsive dizayn',keywords:'css, tailwind, responsive, sass',required:false}],github:true,linkedin:false,status:'active',views:rand(80,140),created:date()},
{id:'hr',title:'İnsan resursları üzrə koordinator',company:'Araz Təhsil',location:'Bakı · Əyani',type:'Tam ştat',description:'Namizədlərlə əlaqələri və işə qəbul sənədlərini sistemli şəkildə idarə edəcək koordinator axtarılır.',responsibilities:'Müraciətlərin təşkili, müsahibə cədvəlləri, sənəd yoxlaması və HR hesabatlarının hazırlanması.',criteria:[{id:'h1',name:'HR təcrübəsi',keywords:'human resources, hr, recruitment, işə qəbul',required:true},{id:'h2',name:'Excel',keywords:'excel, spreadsheet, google sheets',required:false}],github:false,linkedin:true,status:'active',views:rand(50,100),created:date()}
];
const names=[['Aysel','Məmmədova','Rəşad'],['Orxan','Əliyev','Samir'],['Nigar','Həsənli','Murad'],['Tural','Rzayev','İlqar'],['Leyla','Qasımova','Eldar'],['Murad','Səfərov','Azər'],['Günel','Abbasova','Vüqar'],['Elvin','Cəfərov','Ramil'],['Sevinc','Hüseynova','Elşən'],['Kənan','İsmayılov','Fərid'],['Səbinə','Quliyeva','Ramin'],['Nihad','Əsgərov','Faiq']];
const skills=['Python, SQL, IELTS 7.0, Bakı','Python, PostgreSQL, Bakı','Python, IELTS 6.5','HTML, CSS, JavaScript, React','SQL, Python, FastAPI','Django, MySQL, English B2, Bakı','Excel, HR, recruitment','JavaScript, TypeScript, React','Python, Bakı','C++, Linux, Git','HR, Excel, Bakı','React, Tailwind, CSS'];
const applications=names.map((n,i)=>({id:'ap'+i,jobId:i===6||i===10?'hr':i===3||i===7?'front':'python',first:n[0],last:n[1],father:n[2],email:`candidate${i+1}@example.com`,phone:'+994 50 000 '+String(1000+i),city:i%5===0?'Sumqayıt':'Bakı',skills:skills[i],motivation:'Vakansiya ilə maraqlanıram. Müvafiq sahədə təcrübəmi komandanızda tətbiq etmək istəyirəm.',github:i%2===0?'https://github.com/example':'' ,linkedin:i%3===0?'https://www.linkedin.com/in/example/':'',cvText:`${n[0]} ${n[1]} — ${skills[i]}. Təhsil və layihə təcrübəsi.`,cvName:'synthetic-cv.txt',cvData:'',certName:'',certData:'',status:i%6===0?'interview':'new',response:'',replyStatus:i%4===0?'recorded':'none',created:new Date(Date.now()-i*86400000).toISOString(),logs:[]}));
const faqs=[{id:uid(),q:'Vakansiyaya necə müraciət edə bilərəm?',a:'Vakansiyalar səhifəsində uyğun elanı seçin, müraciət formasını doldurun və CV-nizi əlavə edin.'},{id:uid(),q:'Müraciət etdikdən sonra nə baş verir?',a:'Müraciətiniz HR komandası tərəfindən nəzərdən keçirilir. Növbəti addımlar barədə sizinlə göstərdiyiniz e-poçt ünvanı vasitəsilə əlaqə saxlanıla bilər.'},{id:uid(),q:'Müraciət üçün ödəniş tələb olunur?',a:'Xeyr. HireFlow vasitəsilə vakansiyalara müraciət etmək ödənişsizdir.'},{id:uid(),q:'CV-də olmayan bacarığımı necə bildirə bilərəm?',a:'Müraciət formasında bacarıqlar və motivasiya bölməsini doldurun; GitHub və LinkedIn bölmələri aktivdirsə, profil keçidlərinizi də əlavə edə bilərsiniz.'},{id:uid(),q:'Müraciət nəticəsini kim müəyyən edir?',a:'Yekun qərarı işəgötürən və onun HR komandası verir. Platformadakı avtomatik yoxlama yalnız köməkçi göstəricidir.'}];
return {jobs,applications,faqs,messages:[],mailLog:[],audit:[],employees:[{name:'Aylin Məmmədli',role:'HR koordinatoru',experience:'5 il təcrübə',bio:'Namizəd əlaqələri və işə qəbul prosesləri'},{name:'Fərid Əlizadə',role:'İşə qəbul mütəxəssisi',experience:'4 il təcrübə',bio:'Vakansiya planlaşdırılması və müsahibə idarəetməsi'},{name:'Nərgiz Rəhimova',role:'HR əməliyyatları',experience:'6 il təcrübə',bio:'İş axınları və sənəd idarəçiliyi'}],schema:2};};
let state;try{state=JSON.parse(localStorage.getItem(KEY))||defaults();if(!state.jobs||!state.applications)throw Error('bad state')}catch{state=defaults()}
let adminLogged=sessionStorage.getItem(SESSION)==='yes', adminTab='dashboard', activeJob=null, activeApplicant=null, applicantGroup='all', editor=[],editingJob=null, searchValue='', messageSearch='', modal=null, mobileMenu=false, jobViewedSession=new Set(), logoutRequested=false;
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){toast('Yaddaş dolub. Böyük fayllar saxlanmaya bilər.');return false}};
const log=(text)=>{state.audit.unshift({id:uid(),text,at:date()});state.audit=state.audit.slice(0,250);save()};
const toast=t=>{const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(window.__toastT);window.__toastT=setTimeout(()=>el.classList.remove('show'),3600)};
const job=id=>state.jobs.find(j=>j.id===id), applicant=id=>state.applications.find(a=>a.id===id);
const publicStats=()=>({jobs:state.jobs.filter(j=>j.status==='active').length,views:state.jobs.reduce((x,j)=>x+(j.views||0),0),applications:state.applications.length,replies:state.applications.filter(a=>a.replyStatus==='recorded').length});
const matches=(candidate,criterion)=>{const source=[candidate.skills,candidate.cvText,candidate.motivation,candidate.city].filter(Boolean).join(' ').toLocaleLowerCase('az');const words=[criterion.name,...String(criterion.keywords||'').split(',')].map(x=>x.trim().toLocaleLowerCase('az')).filter(x=>x.length>=2);const found=words.find(w=>source.includes(w));return {yes:!!found,evidence:found?`Mətndə “${found}” ifadəsi tapıldı`:'Təsdiqləyici açar söz tapılmadı; əlavə yoxlama tələb olunur.'};};
const evaluate=(a,j)=>{let yes=0;const results=(j?.criteria||[]).map(c=>{let m=matches(a,c);if(m.yes)yes++;return {...c,...m}});return {yes,total:results.length,results,group:yes===results.length&&results.length?'full':yes===0?'none':'partial',missing:results.filter(r=>!r.yes).map(x=>x.name)};};
const groupLabel=x=>x==='full'?'Tam uyğunluq':x==='partial'?'Qismən uyğunluq':'Təsdiqlənməyən meyarlar';
const groupTag=x=>`<span class="tag ${x==='full'?'green':x==='none'?'red':'orange'}">${esc(groupLabel(x))}</span>`;
const brand=()=>`<a class="brand" href="${attr(pathUrl('/'))}" data-route="/" aria-label="HireFlow — Ana səhifə"><span class="brandword">Hire<b>Flow</b></span></a>`;
function asset(p){return new URL(p,document.currentScript?.src||document.querySelector('script[src$="script.js"]')?.src||location.href).href}
const nav=[['/','Ana səhifə'],['/vacancies','Vakansiyalar'],['/about','Haqqımızda'],['/faq','FAQ'],['/contact','Əlaqə']];
const isFile=location.protocol==='file:';
// Derive the deployment prefix from the location of script.js; works at / and /HireFlow/.
const scriptUrl=new URL(document.querySelector('script[src$="script.js"]')?.src||'./script.js',location.href);
const basePath=isFile?'':scriptUrl.pathname.replace(/\/[^/]*$/,'').replace(/\/$/,'');
const getPath=()=>{
  const hashPath=location.hash.startsWith('#/')?location.hash.slice(1):null;
  if(isFile)return hashPath||'/';
  if(hashPath)return hashPath;
  let path=decodeURI(location.pathname);
  if(basePath && (path===basePath || path===basePath+'/'))return '/';
  if(basePath && path.startsWith(basePath+'/'))path=path.slice(basePath.length);
  return path.replace(/\/$/,'')||'/';
};
const pathUrl=p=>isFile?'#'+p:(basePath+(p==='/'?'/':p));
function navigate(path){modal=null;mobileMenu=false;if(isFile){location.hash=path;render()}else{history.pushState({},'',pathUrl(path));render()}window.scrollTo({top:0,behavior:'instant'})}
const link=(p,t,cl='')=>`<a href="${attr(pathUrl(p))}" data-route="${attr(p)}" class="${cl}">${t}</a>`;
const publicNav=(p)=>`<div class="topline">HireFlow · Müraciətlər üçün aydın proses, komandalar üçün rahat idarəetmə</div><header class="site-header"><div class="container nav">${brand()}<nav class="nav-center" aria-label="Əsas menyu">${nav.map(([u,t])=>link(u,esc(t),p===u?'active':'')).join('')}</nav><div class="nav-action">${link('/admin','HR panelinə keçid →','btn sm')}</div><button class="nav-mobile-btn" aria-label="Menyunu aç" data-action="mobile">☰</button></div>${mobileMenu?`<nav class="menu-mobile">${nav.map(([u,t])=>link(u,esc(t))).join('')}${link('/admin','HR paneli')}</nav>`:''}</header>`;
const footer=()=>`<footer class="footer"><div class="container"><div class="footer-top"><div>${brand()}<p>Namizədlərlə şirkətlər arasında işə qəbul prosesini daha aydın və səliqəli qurmaq üçün yaradılmış platforma.</p><p class="tiny">Təqdimat üçün hazırlanmış demo. Məlumatlar bu brauzerdə saxlanılır.</p></div><div><h4>Kəşf edin</h4><div class="footer-links">${nav.slice(0,3).map(([u,t])=>link(u,esc(t))).join('')}</div></div><div><h4>Kömək</h4><div class="footer-links">${link('/faq','Tez-tez verilən suallar')}${link('/contact','Əlaqə')}${link('/admin','HR girişi')}</div></div><div><h4>Bizimlə əlaqə</h4><div class="footer-links"><a href="mailto:hireflow.ai@gmail.com">hireflow.ai@gmail.com</a><span class="small">Bakı, Azərbaycan</span><span class="small">İşə qəbul üçün vahid platforma</span></div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} HireFlow. Bütün hüquqlar qorunur.</span><span>Better People. Stronger Teams.</span></div></div></footer>`;
const publicShell=(p,content)=>publicNav(p)+`<main id="main">${content}</main>`+footer();
function jobCard(j){return `<article class="job-card"><div class="between"><div class="job-logo">${esc(initials(j.company))}</div><span class="tag green"><span class="dot"></span>Aktiv</span></div><div><div class="muted small">${esc(j.company)} · ${esc(j.location)}</div><h3>${esc(j.title)}</h3></div><p class="small">${esc(j.description.slice(0,155))}${j.description.length>155?'…':''}</p><div class="job-meta"><span class="tag">${esc(j.type)}</span><span class="tag">${j.criteria.length} tələb</span></div>${link('/vacancies/'+j.id,'Vakansiyaya bax →','btn light full')}</article>`}
function home(){let s=publicStats(),jobs=state.jobs.filter(j=>j.status==='active').slice(0,3);return publicShell('/',`<section class="hero"><div class="container hero-grid"><div><div class="eyebrow">Yeni nəsil işə qəbul təcrübəsi</div><h1>Doğru fürsət.<br><span style="color:#276aeb">Daha aydın yol.</span></h1><p class="lead">Vakansiyaları rahat kəşf edin, bacarıqlarınızı təqdim edin və müraciət prosesini ilk addımdan etibarən inamla izləyin.</p><div class="hero-actions">${link('/vacancies','Vakansiyalara bax →','btn')}${link('/about','HireFlow haqqında','btn light')}</div><div class="hero-check"><span>Rahat müraciət</span><span>Aydın tələblər</span><span>Səliqəli proses</span></div></div><div class="showcase" aria-label="Platformanın qrafik nümayişi"><div class="showcase-orbit"></div><div class="showcase-orbit two"></div><div class="showcase-card"><div class="between"><div class="flex"><div class="showcase-avatar">H</div><div><b style="display:block">İşə qəbul paneli</b><small class="muted">Ümumi baxış</small></div></div><span class="tag green">● Aktiv</span></div><div class="visual-bars">${[45,68,52,86,64,94,76].map(x=>`<i style="height:${x}%"></i>`).join('')}</div><div class="sep"></div><div class="between"><div><b style="font-size:25px">${s.applications}</b><div class="small muted">Müraciət</div></div><div><b style="font-size:25px">${s.jobs}</b><div class="small muted">Aktiv vakansiya</div></div><span class="tag green">Yenilənir</span></div></div><div class="showcase-float one">✓ Rahat seçim</div><div class="showcase-float two">↗ Aydın mərhələlər</div></div></div></section><section class="container"><div class="stats">${statCards([{n:s.jobs,t:'Aktiv vakansiya'},{n:s.applications,t:'Qeyd olunan müraciət'},{n:s.views,t:'Vakansiya baxışı'},{n:s.replies,t:'Qeyd olunan geri dönüş'}])}</div><p class="tiny muted" style="text-align:right;margin-top:12px">Göstəricilər nümunə məlumatlara və bu brauzerdəki əməliyyatlara əsaslanır; real platforma statistikası deyil.</p></section><section class="section"><div class="container"><div class="section-head"><div class="eyebrow">Niyə HireFlow?</div><h2>Hər addımda sadəlik</h2><p>Vakansiyadan müraciətə qədər bütün prosesin aydın qurulması həm namizədlərin, həm də HR komandalarının işini asanlaşdırır.</p></div><div class="cards3"><div class="feature"><div class="feature-icon">⌕</div><h3>Uyğun vakansiyanı tapın</h3><p>Axtarış və aydın tələblər sayəsində vaxtınızı doğru imkanlara ayırın.</p></div><div class="feature"><div class="feature-icon">▤</div><h3>Bacarıqlarınızı göstərin</h3><p>CV, layihə keçidləri, sertifikat və motivasiyanızı bir müraciətdə təqdim edin.</p></div><div class="feature"><div class="feature-icon">✓</div><h3>Qərarlar nəzarətdədir</h3><p>İşə qəbulun yekun qiymətləndirilməsi hər zaman işəgötürənin səlahiyyətində qalır.</p></div></div></div></section><section class="section alt"><div class="container"><div class="between wrap" style="margin-bottom:27px"><div><div class="eyebrow">Açıq imkanlar</div><h2 style="margin:7px 0">Aktiv vakansiyalar</h2></div>${link('/vacancies','Bütün vakansiyalar →','btn light')}</div><div class="cards3">${jobs.length?jobs.map(jobCard).join(''):'<div class="empty">Hazırda aktiv vakansiya yoxdur.</div>'}</div></div></section><section class="section"><div class="container"><div class="cta"><div><h2>Yeni fürsətə doğru ilk addım.</h2><p>Aydın tələblərlə elanları nəzərdən keçirin və müraciətinizi göndərin.</p></div>${link('/vacancies','Vakansiyaları kəşf et →','btn light')}</div></div></section>`)}
function statCards(arr){return arr.map(x=>`<div class="stat"><b>${esc(x.n)}</b><span>${esc(x.t)}</span></div>`).join('')}
function vacancies(){return publicShell('/vacancies',`<div class="page-hero"><div class="container"><div class="eyebrow">Karyera imkanları</div><h1>Vakansiyalar</h1><p>Sizə uyğun iş imkanlarını axtarın, tələblərlə tanış olun və birbaşa müraciət edin.</p></div></div><section class="section"><div class="container"><div class="filters"><div class="search"><input id="job-search" class="input" placeholder="Vəzifə, şirkət və ya bacarıq axtar…" value="${attr(searchValue)}" aria-label="Vakansiya axtar"></div><select id="job-type" style="max-width:200px"><option value="">Bütün iş formaları</option><option>Tam ştat</option><option>Yarımştat</option><option>Təcrübə</option><option>Uzaqdan</option></select></div><div id="job-count" class="muted small" style="margin-bottom:20px"></div><div class="cards3" id="job-results"></div></div></section>`)}
function updateJobResults(){const result=document.getElementById('job-results');if(!result)return;let q=(document.getElementById('job-search')?.value||'').toLocaleLowerCase('az'),t=document.getElementById('job-type')?.value||'';const list=state.jobs.filter(j=>j.status==='active'&&(!t||j.type===t)&&[j.title,j.company,j.description,j.location,j.criteria.map(c=>c.name).join(' ')].join(' ').toLocaleLowerCase('az').includes(q));result.innerHTML=list.length?list.map(jobCard).join(''):'<div class="empty" style="grid-column:1/-1"><b>Vakansiya tapılmadı</b>Axtarış sözünü dəyişərək yenidən yoxlayın.</div>';document.getElementById('job-count').textContent=`${list.length} aktiv vakansiya tapıldı`}
function jobPage(id){let j=job(id);if(!j||j.status!=='active')return publicShell('',notFound('Bu vakansiya artıq aktiv deyil.'));if(!jobViewedSession.has(j.id)){j.views=(j.views||0)+1;jobViewedSession.add(j.id);save()}return publicShell('',`<div class="page-hero"><div class="container">${link('/vacancies','← Bütün vakansiyalar','section-link')}<div style="margin-top:18px" class="eyebrow">${esc(j.company)}</div><h1>${esc(j.title)}</h1><div class="badge-line"><span class="tag">${esc(j.location)}</span><span class="tag">${esc(j.type)}</span><span class="tag green">Müraciətlər açıqdır</span></div></div></div><section class="section"><div class="container detail-grid"><div><div class="panel"><h3>Vakansiya haqqında</h3><p>${esc(j.description)}</p><div class="sep"></div><h3>İşin əsas istiqamətləri</h3><p>${esc(j.responsibilities||'Vəzifə ilə bağlı ətraflı məlumat seçim mərhələsində paylaşılacaq.')}</p><div class="sep"></div><h3>Əsas bacarıqlar və tələblər</h3>${j.criteria.map(c=>`<div class="criterion"><div><b>${esc(c.name)}</b><div class="small muted">${c.required?'Əsas tələb':'Üstünlük'}</div></div><span class="tag ${c.required?'green':''}">${c.required?'Əsas':'Əlavə'}</span></div>`).join('')}</div></div><aside><div class="panel"><h3>Müraciətinizi göndərin</h3><p class="small">Məlumatlarınızı daxil edin, bacarıqlarınızı izah edin və CV əlavə edin.</p>${applicationForm(j)}<p class="note">Demo versiyası: müraciətlər yalnız bu brauzerin yaddaşında görünür. Fayllar başqa cihazlara ötürülmür.</p></div></aside></div></section>`)}
function applicationForm(j){return `<form id="application-form" data-id="${attr(j.id)}"><div class="form-grid"><div class="field"><label for="first">Ad *</label><input class="input" id="first" name="first" required maxlength="65"></div><div class="field"><label for="last">Soyad *</label><input class="input" id="last" name="last" required maxlength="65"></div><div class="field wide"><label for="father">Ata adı</label><input class="input" id="father" name="father" maxlength="65"></div><div class="field"><label for="email">E-poçt *</label><input type="email" class="input" id="email" name="email" required></div><div class="field"><label for="phone">Telefon *</label><input class="input" id="phone" name="phone" required placeholder="+994 …"></div><div class="field wide"><label for="city">Şəhər / iş formatı</label><input class="input" id="city" name="city" placeholder="Məsələn, Bakı / əyani"></div><div class="field wide"><label for="skills">Bacarıqlarınız *</label><textarea id="skills" name="skills" required placeholder="Python, SQL, təcrübəniz, IELTS və s."></textarea></div><div class="field wide"><label for="motivation">Motivasiya məktubu *</label><textarea id="motivation" name="motivation" required placeholder="Niyə bu vakansiyaya müraciət edirsiniz?"></textarea></div><div class="field wide"><label for="cvfile">CV (PDF, DOCX və ya TXT) *</label><input class="input" type="file" accept=".pdf,.docx,.txt,application/pdf" name="cvfile" id="cvfile" required><small class="field-help">CV-dən mətn çıxarılması internet bağlantısından asılı ola bilər. Maksimum 4 MB.</small></div><div class="field wide"><label for="certfile">Sertifikat (istəyə bağlı)</label><input class="input" type="file" accept=".pdf,.png,.jpg,.jpeg,.txt" id="certfile" name="certfile"><small class="field-help">Maksimum 1 MB. Yalnız kiçik fayllar brauzerdə saxlanılır.</small></div>${j.github?'<div class="field wide"><label for="github">GitHub profiliniz</label><input class="input" name="github" id="github" type="url" placeholder="https://github.com/…"></div>':''}${j.linkedin?'<div class="field wide"><label for="linkedin">LinkedIn profiliniz</label><input class="input" name="linkedin" id="linkedin" type="url" placeholder="https://linkedin.com/in/…"></div>':''}</div><label class="check-row"><input type="checkbox" required name="consent"> <span class="small">Məlumatlarımın bu demo brauzer yaddaşında saxlanılmasını qəbul edirəm.</span></label><button class="btn full" type="submit">Müraciət göndər →</button></form>`}
function about(){let team=state.employees;return publicShell('/about',`<div class="page-hero"><div class="container"><div class="eyebrow">Bizim yanaşmamız</div><h1>Haqqımızda</h1><p>İnsanları və imkanları bir-birinə yaxınlaşdırmaq üçün daha anlaşıqlı işə qəbul təcrübəsi qururuq.</p></div></div><section class="section"><div class="container about-split"><div><div class="eyebrow">Sadəlikdən başlayırıq</div><h2>İşə qəbul mürəkkəb olmamalıdır.</h2><p>HireFlow vakansiya məlumatlarının təqdim edilməsindən namizəd müraciətlərinin idarəsinə qədər prosesi bir yerdə toplamaq üçün hazırlanır.</p><p>Məqsədimiz namizədlərin iş elanlarını rahat anlaması, işəgötürənlərin isə müraciətləri sistemli şəkildə nəzərdən keçirə bilməsidir. Yekun işə qəbul qərarı hər zaman insan tərəfindən verilir.</p>${link('/vacancies','Açıq vakansiyalara bax →','btn')}</div><div class="about-art"><div class="about-wordmark" aria-label="HireFlow"><span>Hire<b>Flow</b></span><small>Better People. Stronger Teams.</small></div></div></div></section><section class="section alt"><div class="container"><div class="section-head"><div class="eyebrow">Komanda</div><h2>İnsan yönümlü yanaşma</h2><p>Aşağıdakı HR profilləri təqdimat məqsədli nümunələrdir; real şirkət əməkdaşları kimi təqdim edilmir.</p></div><div class="cards3">${team.map(h=>`<article class="profile-card"><div class="avatar">${esc(initials(h.name))}</div><h3>${esc(h.name)}</h3><div class="muted small">${esc(h.role)}</div><div style="margin:15px 0"><span class="tag">${esc(h.experience)}</span></div><p class="small">${esc(h.bio)}</p></article>`).join('')}</div></div></section><section class="section"><div class="container"><div class="cta"><div><h2>Daha rahat işə qəbul təcrübəsi.</h2><p>Bir sualınız və ya təklifiniz varsa, bizimlə əlaqə saxlayın.</p></div>${link('/contact','Bizə yazın →','btn light')}</div></div></section>`)}
function faq(){return publicShell('/faq',`<div class="page-hero"><div class="container"><div class="eyebrow">Dəstək</div><h1>Tez-tez verilən suallar</h1><p>Müraciət, CV və işə qəbul mərhələləri haqqında ən çox verilən sualların cavabları.</p></div></div><section class="section"><div class="container"><div class="faq-list">${state.faqs.length?state.faqs.map(x=>`<details class="faq-item"><summary>${esc(x.q)}</summary><p>${esc(x.a)}</p></details>`).join(''):'<div class="empty">Hazırda sual-cavab yoxdur.</div>'}<div class="panel" style="margin-top:25px"><h3>Axtardığınız cavabı tapmadınız?</h3><p>Komandamıza sualınızı göndərə bilərsiniz.</p>${link('/contact','Əlaqə saxlayın →','btn')}</div></div></div></section>`)}
function contact(){return publicShell('/contact',`<div class="page-hero"><div class="container"><div class="eyebrow">Əlaqə</div><h1>Bizimlə danışın</h1><p>Sual, təklif və əməkdaşlıq müraciətləriniz üçün bizə yazın.</p></div></div><section class="section"><div class="container contact-grid"><div><h2>Əlaqə məlumatları</h2><p>Sizə kömək etmək və fikirlərinizi dinləmək üçün buradayıq.</p><div class="contact-point"><div class="feature-icon" style="margin:0">✉</div><div><b>E-poçt ünvanımız</b><a class="section-link" href="mailto:hireflow.ai@gmail.com">hireflow.ai@gmail.com</a></div></div><div class="contact-point"><div class="feature-icon" style="margin:0">⌖</div><div><b>Fəaliyyət bölgəsi</b><span class="muted">Bakı, Azərbaycan</span></div></div><div class="alert">Demo rejimində bu forma göndərilən mesajları yalnız brauzer yaddaşına yazır. Real e-poçt bildirişi göndərilmir.</div></div><div class="panel"><h3>Mesaj göndərin</h3><form id="contact-form"><div class="form-grid"><div class="field"><label>Ad *</label><input class="input" name="first" required></div><div class="field"><label>Soyad *</label><input class="input" name="last" required></div><div class="field"><label>E-poçt *</label><input type="email" class="input" name="email" required></div><div class="field"><label>Telefon *</label><input class="input" name="phone" required></div><div class="field wide"><label>Mesajınız *</label><textarea name="message" required minlength="8" placeholder="Sizə necə kömək edə bilərik?"></textarea></div></div><button class="btn" type="submit">Mesajı göndər →</button></form></div></div></section>`)}
const notFound=t=>`<section class="section"><div class="container"><div class="empty"><h2>Səhifə tapılmadı</h2><p>${esc(t||'Axtardığınız səhifə mövcud deyil.')}</p>${link('/','Ana səhifəyə qayıt','btn')}</div></div></section>`;
function login(){return `<div class="login-wrap"><div class="login-card">${brand()}<div class="eyebrow">İdarəetmə girişi</div><h2 style="margin:9px 0 12px">HR paneli</h2><p>Vakansiyaları, müraciətləri və sayt məzmununu bir mərkəzdən idarə edin.</p><form id="login-form"><div class="field"><label>E-poçt</label><input type="email" name="email" class="input" autocomplete="username" required placeholder="admin@hireflow.local"></div><div class="field"><label>Şifrə</label><input type="password" name="password" class="input" autocomplete="current-password" required placeholder="Şifrəniz"></div><button type="submit" class="btn full">Panelə daxil ol →</button></form><div class="sep"></div><button data-action="demo-login" class="btn light full">Demo hesabı ilə daxil ol</button><p class="note" style="margin-top:17px">Təhlükəsizlik qeydi: bu giriş yalnız nümayiş üçündür. Backend olmadan real admin icazəsi təmin edilmir.</p><div style="text-align:center;margin-top:14px">${link('/','← Sayta qayıt','section-link')}</div></div></div>`}
const adminLinks=[['dashboard','▦','Ümumi baxış'],['vacancies','▤','Vakansiyalar'],['new','＋','Yeni vakansiya'],['requests','◉','Müraciətlər'],['messages','✉','Əlaqə sorğuları'],['faqs','?','FAQ idarəetməsi'],['history','↺','Fəaliyyət tarixçəsi']];
function adminShell(content){return `<div class="admin"><aside class="sidebar">${brand()}<nav aria-label="Admin menyusu">${adminLinks.map(([k,i,t])=>`<a href="${pathUrl('/admin/'+k)}" data-admin="${k}" class="${adminTab===k?'active':''}"><span style="font-size:19px;width:24px">${i}</span> ${t}</a>`).join('')}</nav><div class="sidebar-footer"><a href="${pathUrl('/')}" data-route="/">↗ Sayta bax</a><button data-action="logout">⇥ Çıxış</button></div></aside><div class="admin-main"><div class="admin-top"><div class="small muted">HireFlow / <b>${esc(adminLinks.find(x=>x[0]===adminTab)?.[2]||'İdarəetmə')}</b></div><div class="flex wrap"><span class="tag orange">Demo / localStorage</span><span class="tag">HR administratoru</span></div></div><div class="admin-content">${content}</div></div></div>`}
function head(t,sub='',extra=''){return `<div class="between wrap" style="margin-bottom:23px"><div><div class="eyebrow">İdarəetmə paneli</div><h1>${esc(t)}</h1><p style="margin:0">${esc(sub)}</p></div>${extra}</div>`}
function adminDashboard(){let s=publicStats(), apps=state.applications, act=state.jobs.filter(j=>j.status==='active');return head('Ümumi baxış','Vakansiyaların, müraciətlərin və əlaqə prosesinin icmalı.',`<button class="btn light sm" data-action="export">↓ CSV ixrac</button>`)+`<div class="alert warn">Göstəricilər bu brauzerdəki demo məlumatlara aiddir. Namizədlərin uyğunluq dərəcələri və müsahibə qərarları ictimai statistikaya daxil edilmir.</div><div class="stats">${statCards([{n:s.jobs,t:'Aktiv vakansiya'},{n:s.applications,t:'CV müraciəti'},{n:s.replies,t:'Geri dönüş qeydiyyatı'},{n:state.messages.length,t:'Əlaqə sorğusu'}])}</div><div class="admin-grid" style="margin-top:22px"><div class="panel"><div class="between"><h3>Aktiv vakansiyalar</h3><button data-admin="vacancies" class="btn light sm">Hamısı →</button></div><div class="table-wrap"><table><thead><tr><th>Vakansiya</th><th>Baxış</th><th>Müraciət</th><th>Status</th></tr></thead><tbody>${act.map(j=>`<tr><td><b>${esc(j.title)}</b><div class="small muted">${esc(j.company)}</div></td><td>${j.views||0}</td><td>${apps.filter(a=>a.jobId===j.id).length}</td><td><span class="tag green">Aktiv</span></td></tr>`).join('')||'<tr><td colspan="4">Aktiv vakansiya yoxdur.</td></tr>'}</tbody></table></div></div><div class="panel"><h3>Son fəaliyyətlər</h3><div class="timeline">${state.audit.slice(0,7).map(x=>`<div class="timeline-item"><div class="small">${esc(x.text)}</div><time>${formatDate(x.at)}</time></div>`).join('')||'<p class="small">Hələ yeni əməliyyat qeydə alınmayıb.</p>'}</div></div></div><div class="panel" style="margin-top:20px"><h3>Son müraciətlər</h3>${applicationTable(apps.slice().sort((a,b)=>b.created.localeCompare(a.created)).slice(0,7),false)}</div>`}
function adminVacancies(){return head('Vakansiyalar','Vakansiyaları aktivləşdirin, deaktiv edin və şərtləri yeniləyin.',`<button data-admin="new" class="btn">+ Yeni vakansiya</button>`)+`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Vakansiya</th><th>Meyarlar</th><th>Baxış</th><th>Müraciət</th><th>Status</th><th>Əməliyyat</th></tr></thead><tbody>${state.jobs.map(j=>`<tr><td><b>${esc(j.title)}</b><div class="muted small">${esc(j.company)}</div></td><td>${j.criteria.length}</td><td>${j.views||0}</td><td>${state.applications.filter(a=>a.jobId===j.id).length}</td><td><span class="tag ${j.status==='active'?'green':'red'}">${j.status==='active'?'Aktiv':'Deaktiv'}</span></td><td><div class="table-actions"><button class="btn sm light" data-action="edit-job" data-id="${attr(j.id)}">Düzəliş</button><button class="btn sm ${j.status==='active'?'danger':'light'}" data-action="toggle-job" data-id="${attr(j.id)}">${j.status==='active'?'Deaktiv et':'Aktiv et'}</button></div></td></tr>`).join('')}</tbody></table></div></div>`}
function newJob(){let j=editingJob?job(editingJob):null;if(!editor.length)editor=structuredClone(j?.criteria||[{id:uid(),name:'',keywords:'',required:true}]);return head(j?'Vakansiyanı redaktə et':'Yeni vakansiya','Şərtləri və namizəd müraciət formasını tənzimləyin.')+`<form id="job-editor" data-id="${attr(j?.id||'')}"><div class="panel"><h3>Əsas məlumatlar</h3><div class="form-grid"><div class="field"><label>Vakansiyanın adı *</label><input class="input" name="title" value="${attr(j?.title||'')}" required></div><div class="field"><label>Şirkətin adı *</label><input class="input" name="company" value="${attr(j?.company||'')}" required></div><div class="field"><label>İş yeri / formatı *</label><input class="input" name="location" value="${attr(j?.location||'Bakı · Əyani')}" required></div><div class="field"><label>İş rejimi</label><select name="type">${['Tam ştat','Yarımştat','Təcrübə','Uzaqdan'].map(t=>`<option ${j?.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field wide"><label>Vakansiya haqqında məlumat *</label><textarea name="description" required minlength="30">${esc(j?.description||'')}</textarea></div><div class="field wide"><label>Vəzifə öhdəlikləri</label><textarea name="responsibilities">${esc(j?.responsibilities||'')}</textarea></div></div></div><div class="panel"><div class="between wrap"><div><h3>Namizəd meyarları</h3><p class="small">Meyar adı və sinonim açar sözlər CV mətnində yoxlanacaq. Sözləri vergüllə ayırın.</p></div><button type="button" class="btn sm light" data-action="add-criterion">+ Bacarıq əlavə et</button></div><div id="criteria-list" class="criteria-editor">${criteriaEditor()}</div></div><div class="panel"><h3>Müraciət forması</h3><p class="small">Ad, soyad, e-poçt, telefon, bacarıq, motivasiya və CV yükləmə bütün vakansiyalarda mövcuddur.</p><label class="check-row"><input type="checkbox" name="github" ${j?.github||!j?'checked':''}> GitHub profil keçidi göstərilsin</label><label class="check-row"><input type="checkbox" name="linkedin" ${j?.linkedin||!j?'checked':''}> LinkedIn profil keçidi göstərilsin</label><div class="sep"></div><label class="check-row"><input type="checkbox" name="active" ${j?.status!=='inactive'?'checked':''}> Vakansiya aktiv yayımlansın</label></div><div class="flex wrap" style="margin-top:22px"><button type="submit" class="btn">${j?'Dəyişiklikləri saxla':'Vakansiyanı yarat'} →</button><button type="button" data-admin="vacancies" class="btn light">Ləğv et</button></div></form>`}
function criteriaEditor(){return editor.map((c,i)=>`<div class="editor-row" data-index="${i}"><div><label>Meyarın adı *</label><input class="input" data-criterion="name" data-index="${i}" value="${attr(c.name)}" placeholder="Məsələn, SQL"></div><div><label>Açar sözlər / alternativlər</label><input class="input" data-criterion="keywords" data-index="${i}" value="${attr(c.keywords)}" placeholder="SQL, PostgreSQL, MySQL"><small>Vergüllə ayrılmış sözlər; çox sinonim əlavə edilə bilər.</small></div><div><label class="check-row"><input type="checkbox" data-criterion="required" data-index="${i}" ${c.required?'checked':''}> Əsas</label><button type="button" class="btn danger sm" data-action="remove-criterion" data-index="${i}" aria-label="Meyarı sil">Sil</button></div></div>`).join('')}
function applicationsFor(j){return state.applications.filter(a=>a.jobId===j.id)}
function adminRequests(){let jobs=state.jobs;return head('Müraciətlər','Vakansiya üzrə baxışlar, müraciətlər və namizəd qrupları.')+`<div style="display:grid;gap:17px">${jobs.map(j=>{let a=applicationsFor(j),interview=a.filter(x=>x.status==='interview').length;return `<div class="panel"><div class="between wrap"><div><h3 style="margin-bottom:5px">${esc(j.title)}</h3><div class="small muted">${esc(j.company)} · <span class="tag ${j.status==='active'?'green':'red'}">${j.status==='active'?'Aktiv':'Deaktiv'}</span></div></div><button data-action="open-requests" data-id="${attr(j.id)}" class="btn light">Ətraflı →</button></div><div class="badge-line" style="margin-top:18px"><span class="tag">${j.views||0} baxış</span><span class="tag">${a.length} müraciət</span><span class="tag">${interview} müsahibə statusu</span><span class="tag">${j.criteria.length} meyar</span></div></div>`}).join('')}</div>`}
function applicantDetailsLink(a){return `<button class="btn light sm" data-action="open-applicant" data-id="${attr(a.id)}">Ətraflı →</button>`}
function applicationTable(a,showMatch=true){return `<div class="table-wrap"><table><thead><tr><th>Namizəd</th><th>Vakansiya</th>${showMatch?'<th>Meyar nəticəsi</th>':''}<th>Tarix</th><th>Status</th><th></th></tr></thead><tbody>${a.map(x=>{let j=job(x.jobId),e=evaluate(x,j);return `<tr><td><b>${esc(x.first+' '+x.last)}</b><div class="muted small">${esc(x.email)}</div></td><td>${esc(j?.title||'—')}</td>${showMatch?`<td><b>${e.yes}/${e.total}</b><div class="tiny muted">${esc(groupLabel(e.group))}</div></td>`:''}<td>${formatDate(x.created)}</td><td><span class="tag">${esc(statusLabel(x.status))}</span></td><td>${applicantDetailsLink(x)}</td></tr>`}).join('')||'<tr><td colspan="6">Namizəd tapılmadı.</td></tr>'}</tbody></table></div>`}
const statusLabel=x=>({new:'Yeni',review:'Yoxlanılır',documents:'Sənəd gözlənilir',interview:'Müsahibə',offer:'Təklif',closed:'Bağlanıb'})[x]||x;
function adminJobRequests(id){let j=job(id);if(!j)return '<div class="empty">Vakansiya yoxdur.</div>';let a=applicationsFor(j),groups={full:[],partial:[],none:[]};a.forEach(x=>groups[evaluate(x,j).group].push(x));return head(j.title,`${j.company} · ${a.length} müraciət`,`<button class="btn light" data-admin="requests">← Müraciətlər</button>`)+`<div class="stats" style="margin:0 0 20px">${statCards([{n:j.views||0,t:'Görüntülənmə'},{n:a.length,t:'Müraciət'},{n:groups.full.length,t:'Tam uyğunluq'},{n:a.filter(x=>x.status==='interview').length,t:'Müsahibə statusu'}])}</div><div class="panel" style="margin-bottom:18px"><div class="between wrap"><div><h3 style="margin:0 0 5px">CV-lərin toplu idxalı</h3><p class="small" style="margin:0">PDF, DOCX və TXT fayllarını əlavə edin; PDF/DOCX oxunması üçün internet bağlantısı lazımdır.</p></div><button class="btn light sm" data-action="seed-hundred" data-id="${attr(j.id)}">+ 100 sintetik namizəd</button></div><form id="bulk-cv" data-id="${attr(j.id)}" class="flex wrap" style="margin-top:15px"><input class="input" style="flex:1;min-width:210px" type="file" name="bulkFiles" multiple accept=".pdf,.docx,.txt"><button class="btn sm" type="submit">CV-ləri idxal et</button></form><p class="note" style="margin:8px 0 0">Toplu CV idxalı zamanı şəxsi sahələr avtomatik təsdiqlənmir. Namizəd məlumatları fayl adından ilkin doldurulur, HR sonradan yoxlamalıdır.</p></div><div class="alert warn" style="margin-bottom:20px">Açar söz analizi yalnız ilkin yardımçı yoxlamadır. CV-də sözün tapılmaması bacarığın olmaması demək deyil. Namizədlərin yekun qiymətləndirilməsi HR tərəfindən aparılır.</div><div class="tabs">${[['full','Tam uyğunluq',groups.full.length],['partial','Qismən uyğunluq',groups.partial.length],['none','Təsdiqlənməyənlər',groups.none.length],['all','Hamısı',a.length]].map(([key,label,n])=>`<button class="tab ${applicantGroup===key?'active':''}" data-action="switch-group" data-group="${key}">${label} (${n})</button>`).join('')}</div><div class="panel">${applicationTable(applicantGroup==='all'?a:groups[applicantGroup]||[],true)}</div>`}
function evidenceList(a,j){let e=evaluate(a,j);return `<div class="between wrap"><div><h3 style="margin:0">Meyar yoxlaması</h3><div class="small muted">${e.yes}/${e.total} meyar üçün mətn göstəricisi tapılıb</div></div>${groupTag(e.group)}</div><div class="sep"></div>${e.results.map(r=>`<div class="criterion"><div><b>${esc(r.name)}</b><div class="small muted">${esc(r.evidence)}</div><div class="tiny muted">${r.required?'Əsas tələb':'Üstünlük'}</div></div><span class="tag ${r.yes?'green':'orange'}">${r.yes?'Tapılıb':'Yoxlama'}</span></div>`).join('')}<div class="alert warn" style="margin-top:18px">Bu nəticə real süni intellekt rəyi deyil: mətn və açar söz uyğunluğudur. Semantik yoxlama, kontekst və sübutların təsdiqi HR-ın öhdəliyindədir.</div>`}
function personDetail(id){let a=applicant(id);if(!a)return head('Namizəd tapılmadı');let j=job(a.jobId),e=evaluate(a,j);return head(a.first+' '+a.last,`Ata adı: ${a.father||'—'} · ${j?.title||'Vakansiya'}`,`<button data-action="back-requests" class="btn light">← Müraciətlərə qayıt</button>`)+`<div class="detail-grid"><div><div class="panel"><h3>Şəxsi məlumatlar</h3><div class="form-grid">${[['Ad',a.first],['Soyad',a.last],['Ata adı',a.father||'—'],['E-poçt',a.email],['Telefon',a.phone],['Şəhər / iş formatı',a.city||'—'],['GitHub',a.github||'—'],['LinkedIn',a.linkedin||'—']].map(([k,v])=>`<div class="field"><label>${esc(k)}</label><div class="small" style="overflow-wrap:anywhere">${/^https:\/\//.test(v)?`<a href="${attr(v)}" target="_blank" rel="noopener noreferrer" class="section-link">${esc(v)} ↗</a>`:esc(v)}</div></div>`).join('')}</div><div class="sep"></div><h3>Bacarıqlar</h3><p>${esc(a.skills)}</p><h3>Motivasiya</h3><p>${esc(a.motivation)}</p><div class="sep"></div><h3>Əlavə olunan sənədlər</h3><div class="between wrap"><span class="small">CV: <b>${esc(a.cvName||'əlavə edilməyib')}</b></span>${a.cvData?`<button data-action="download-file" data-id="${attr(a.id)}" data-kind="cv" class="btn sm light">CV-ni aç / yüklə</button>`:''}</div>${a.cvText?`<details style="margin-top:12px"><summary class="section-link" style="cursor:pointer">CV-dən oxunmuş mətn</summary><div class="preview-box" style="margin-top:10px;max-height:220px;overflow:auto">${esc(a.cvText.slice(0,8000))}</div></details>`:''}<div class="between wrap" style="margin-top:12px"><span class="small">Sertifikat: <b>${esc(a.certName||'əlavə edilməyib')}</b></span>${a.certData?`<button data-action="download-file" data-id="${attr(a.id)}" data-kind="cert" class="btn sm light">Sertifikatı aç / yüklə</button>`:''}</div></div><div class="panel"><h3>Əlavə məlumat və cavab</h3><p class="small">Namizədin göndərdiyi yeni məlumatı burada qeyd edin. Nəticə avtomatik yenidən hesablanacaq.</p><form id="candidate-reply" data-id="${attr(a.id)}"><div class="field"><label>Namizədin yeni cavabı</label><textarea name="reply" required placeholder="Məsələn: PostgreSQL ilə 2 il işləmişəm."></textarea></div><button class="btn light sm" type="submit">Məlumatı əlavə et və yenilə</button></form></div><div class="panel"><h3>Yazışma tarixçəsi</h3>${state.mailLog.filter(x=>x.applicantId===a.id).map(m=>`<div class="timeline-item" style="margin-bottom:14px"><div class="small"><b>${esc(m.subject)}</b><br>${esc(m.body.slice(0,180))}${m.body.length>180?'…':''}</div><div class="tiny muted">${esc(m.state)} · ${formatDate(m.created)}</div></div>`).join('')||'<p class="small">Hələ məktub layihəsi yoxdur.</p>'}</div></div><aside><div class="panel">${evidenceList(a,j)}</div><div class="panel"><h3>HR qərarı və mərhələ</h3><div class="field"><label>Müraciətin statusu</label><select id="candidate-status" data-id="${attr(a.id)}">${['new','review','documents','interview','offer','closed'].map(x=>`<option value="${x}" ${a.status===x?'selected':''}>${statusLabel(x)}</option>`).join('')}</select></div><p class="small muted">Yekun seçim və müsahibə qərarı HR əməkdaşı tərəfindən verilir.</p><button class="btn full" data-action="compose" data-id="${attr(a.id)}">Məktub / müsahibə dəvəti →</button></div><div class="panel"><h3>İlkin analiz qeydi</h3><p class="small">${e.yes===e.total?'Bütün müəyyən edilmiş meyarlar üzrə açar söz göstəricisi tapıldı. Məlumatlar HR tərəfindən təsdiqlənməlidir.':e.yes===0?'Meyarlar üzrə təsdiqləyici açar söz müəyyən edilmədi. Bu, uyğunluğun olmadığına dair qəti nəticə deyil; namizəddən əlavə məlumat tələb oluna bilər.':`${e.total} meyardan ${e.yes}-i üzrə mətn göstəricisi tapıldı. Digər ${e.total-e.yes} meyar üçün əlavə məlumatın dəqiqləşdirilməsi məqsədəuyğundur.`}</p><p class="tiny muted">Nəticə avtomatik mətn yoxlaması əsasında hazırlanır, işə qəbul qərarı deyil.</p></div></aside></div>`}
function adminMessages(){return head('Əlaqə sorğuları','Saytın əlaqə formasından daxil olan mesajlar.')+`<div class="panel">${state.messages.length?state.messages.slice().reverse().map(m=>`<div style="padding:19px 0;border-bottom:1px solid var(--line)"><div class="between wrap"><div><b>${esc(m.first+' '+m.last)}</b><div class="small muted">${formatDate(m.created)}</div></div><span class="tag ${m.status==='answered'?'green':''}">${m.status==='answered'?'Cavab qeydə alınıb':'Yeni sorğu'}</span></div><p style="margin:12px 0;white-space:pre-wrap">${esc(m.message)}</p><div class="badge-line"><a class="section-link" href="mailto:${attr(m.email)}">${esc(m.email)}</a><span class="small muted">${esc(m.phone)}</span></div><div class="flex wrap" style="margin-top:13px"><button class="btn sm light" data-action="reply-contact" data-id="${attr(m.id)}">E-poçt layihəsi aç</button><button class="btn sm light" data-action="mark-contact" data-id="${attr(m.id)}">Cavabı qeydə al</button></div></div>`).join(''):'<div class="empty">Hələ əlaqə sorğusu yoxdur.</div>'}</div>`}
function adminFaqs(){return head('FAQ idarəetməsi','Sualları istənilən vaxt əlavə edin, dəyişdirin və silin.')+`<div class="admin-grid"><div class="panel"><h3>Yayımlanan suallar</h3>${state.faqs.map(f=>`<div style="border-bottom:1px solid var(--line);padding:13px 0"><div class="between"><b>${esc(f.q)}</b><div class="table-actions"><button data-action="edit-faq" data-id="${attr(f.id)}" class="btn light sm">Düzəlt</button><button data-action="delete-faq" data-id="${attr(f.id)}" class="btn danger sm">Sil</button></div></div><p class="small" style="margin:8px 0 0">${esc(f.a)}</p></div>`).join('')}</div><div class="panel"><h3>Yeni sual əlavə et</h3><form id="faq-form"><div class="field"><label>Sual *</label><input class="input" name="question" required></div><div class="field"><label>Cavab *</label><textarea name="answer" required></textarea></div><button class="btn" type="submit">Əlavə et →</button></form></div></div>`}
function adminHistory(){return head('Fəaliyyət tarixçəsi','Brauzerdə qeydə alınan əməliyyatlar.')+`<div class="panel"><div class="timeline">${state.audit.map(x=>`<div class="timeline-item"><b class="small">${esc(x.text)}</b><div class="tiny muted">${new Date(x.at).toLocaleString('az-AZ')}</div></div>`).join('')||'<p>Fəaliyyət yoxdur.</p>'}</div></div>`}
function adminPage(path){let seg=path.split('/').filter(Boolean);if(!adminLogged)return login();if(seg[1]==='applicant'&&seg[2]){adminTab='requests';return adminShell(personDetail(seg[2]))}if(seg[1]==='requests'&&seg[2]){adminTab='requests';return adminShell(adminJobRequests(seg[2]))}adminTab=adminLinks.some(x=>x[0]===seg[1])?seg[1]:'dashboard';let body=({dashboard:adminDashboard,vacancies:adminVacancies,new:newJob,requests:adminRequests,messages:adminMessages,faqs:adminFaqs,history:adminHistory})[adminTab]();return adminShell(body)}
function composeModal(id){let a=applicant(id),j=job(a.jobId),e=evaluate(a,j);let body=e.missing.length?`Hörmətli ${a.first} ${a.last},\n\n${j.title} vakansiyasına müraciətiniz üçün təşəkkür edirik. Müraciətinizlə bağlı aşağıdakı məlumatları dəqiqləşdirməyinizi xahiş edirik: ${e.missing.join(', ')}.\n\nCavabınızı bu e-poçta göndərə bilərsiniz.\n\nHörmətlə,\n${j.company} HR komandası`:`Hörmətli ${a.first} ${a.last},\n\n${j.title} vakansiyasına müraciətiniz üçün təşəkkür edirik. Müraciətiniz nəzərdən keçirilir. Növbəti mərhələ barədə sizinlə ayrıca əlaqə saxlanılacaq.\n\nHörmətlə,\n${j.company} HR komandası`;
return `<div class="modal-back" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="Məktub hazırla"><div class="between"><h3>Namizədə məktub</h3><button class="btn ghost sm" data-action="close-modal">✕</button></div><div class="alert warn">Yalnız e-poçt layihəsi hazırlanır. “E-poçt tətbiqində aç” düyməsi poçt proqramınızı açır; göndərilmə avtomatik təsdiqlənmir.</div><form id="mail-form" data-id="${attr(a.id)}"><div class="form-grid" style="margin-top:17px"><div class="field"><label>Göndərən HR e-poçtu *</label><input type="email" class="input" required name="sender" value="hireflow.ai@gmail.com"></div><div class="field"><label>Alıcı</label><input class="input" readonly value="${attr(a.email)}"></div><div class="field wide"><label>Məktub növü</label><select id="mail-kind"><option value="info">Məlumat dəqiqləşdirmə / status</option><option value="interview">Müsahibəyə dəvət</option></select></div><div class="field wide hide" id="meeting-fields"><label>Müsahibə tarixi və saatı</label><input class="input" id="meeting-time" type="datetime-local"><label style="margin-top:12px">Görüş yeri və ya keçid</label><input class="input" id="meeting-location" placeholder="Bakı ofisi / onlayn görüş keçidi"></div><div class="field wide"><label>Mövzu</label><input class="input" name="subject" required value="${attr(j.title+' — müraciətiniz barədə')}"></div><div class="field wide"><label>Məktub mətni</label><textarea style="min-height:210px" name="body" required>${esc(body)}</textarea></div></div><div class="flex wrap"><button class="btn" type="submit">Layihəni yadda saxla</button><button type="button" class="btn light" data-action="open-email" data-id="${attr(a.id)}">E-poçt tətbiqində aç ↗</button></div><p class="note">Demo rejimi serverdən e-poçt göndərə bilməz. Göndərişdən sonra vəziyyəti ayrıca qeydə alın.</p></form><button data-action="mark-replied" data-id="${attr(a.id)}" class="btn light sm" style="margin-top:10px">Göndərildiyini əl ilə qeyd et</button></div></div>`}
function faqModal(id){let f=state.faqs.find(x=>x.id===id);return `<div class="modal-back" data-action="close-modal"><div class="modal" role="dialog"><div class="between"><h3>FAQ redaktə et</h3><button class="btn ghost sm" data-action="close-modal">✕</button></div><form id="edit-faq-form" data-id="${attr(id)}"><div class="field"><label>Sual</label><input class="input" name="q" required value="${attr(f.q)}"></div><div class="field"><label>Cavab</label><textarea name="a" required>${esc(f.a)}</textarea></div><button class="btn">Saxla</button></form></div></div>`}
function render(){const p=getPath();document.title=(p==='/admin'||p.startsWith('/admin/'))?'HR paneli · HireFlow':'HireFlow — Daha aydın işə qəbul';const app=document.getElementById('app');app.innerHTML=p.startsWith('/admin')?adminPage(p):p==='/'?home():p==='/vacancies'?vacancies():p.startsWith('/vacancies/')?jobPage(p.split('/')[2]):p==='/about'?about():p==='/faq'?faq():p==='/contact'?contact():publicShell(p,notFound());if(modal)app.insertAdjacentHTML('beforeend',modal);updateJobResults();}
function routeAdmin(tab){if(tab==='new'){editingJob=null;editor=[]}activeJob=null;activeApplicant=null;navigate('/admin/'+tab)}
function safeUrl(x){try{let u=new URL(x);return /^https?:$/.test(u.protocol)?u.href:''}catch{return ''}}
function fileData(file,max){return new Promise((resolve,reject)=>{if(!file)return resolve('');if(file.size>max)return resolve('');let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Fayl oxunmadı'));r.readAsDataURL(file)})}
let cdnCache={};function loadScript(url){if(cdnCache[url])return cdnCache[url];return cdnCache[url]=new Promise((ok,bad)=>{let s=document.createElement('script');s.src=url;s.onload=ok;s.onerror=()=>{delete cdnCache[url];bad(new Error('Kitabxana yüklənmədi'))};document.head.appendChild(s)})}
async function extractCV(file){let ext=(file.name.split('.').pop()||'').toLowerCase();if(ext==='txt')return await file.text();if(ext==='docx'){await loadScript('https://cdn.jsdelivr.net/npm/mammoth@1.9.1/mammoth.browser.min.js');let result=await window.mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});return result.value||''}if(ext==='pdf'){await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';let pdf=await window.pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;let parts=[];for(let i=1;i<=Math.min(pdf.numPages,30);i++){let page=await pdf.getPage(i);parts.push((await page.getTextContent()).items.map(x=>x.str).join(' '))}return parts.join('\n')}throw new Error('Yalnız PDF, DOCX və TXT faylları dəstəklənir')}
async function submitApplication(form){let f=new FormData(form),j=job(form.dataset.id),file=f.get('cvfile'),cert=f.get('certfile');if(!j||j.status!=='active')return toast('Vakansiya aktiv deyil.');if(!(file instanceof File)||!file.size)return toast('CV əlavə edin.');if(file.size>4*1024*1024)return toast('CV maksimum 4 MB ola bilər.');if(!/\.(pdf|docx|txt)$/i.test(file.name))return toast('CV yalnız PDF, DOCX və TXT ola bilər.');if(cert instanceof File&&cert.size>1024*1024)return toast('Sertifikat maksimum 1 MB ola bilər.');let cvText='',cvData='',certData='';const btn=form.querySelector('[type=submit]');btn.disabled=true;btn.textContent='Müraciət yoxlanılır…';try{try{cvText=await extractCV(file)}catch(err){toast('CV mətni oxunmadı; digər məlumatlarla müraciət saxlanacaq.')}cvData=await fileData(file,250000);certData=await fileData(cert,250000);let a={id:uid(),jobId:j.id,first:f.get('first').trim(),last:f.get('last').trim(),father:f.get('father').trim(),email:f.get('email').trim(),phone:f.get('phone').trim(),city:f.get('city').trim(),skills:f.get('skills').trim(),motivation:f.get('motivation').trim(),github:safeUrl(f.get('github')||''),linkedin:safeUrl(f.get('linkedin')||''),cvName:file.name,cvData,cvText:cvText.slice(0,90000),certName:cert?.size?cert.name:'',certData,status:'new',replyStatus:'none',response:'',created:date(),logs:[]};state.applications.push(a);if(!save()){state.applications.pop();return}log(`${a.first} ${a.last} — ${j.title} vakansiyasına müraciət etdi`);form.reset();toast('Müraciətiniz bu brauzerin demo yaddaşında saxlanıldı.');}catch(err){toast('Müraciət saxlanmadı: '+err.message)}finally{btn.disabled=false;btn.textContent='Müraciət göndər →'}}
function changeStatus(id,s){let a=applicant(id);if(!a)return;a.status=s;log(`${a.first} ${a.last} — mərhələ: ${statusLabel(s)}`);toast('Status yeniləndi');render()}
function mailFromForm(form){let a=applicant(form.dataset.id),data=new FormData(form);if(!a)return null;return {applicantId:a.id,to:a.email,from:String(data.get('sender')||'').trim(),subject:String(data.get('subject')||'').trim(),body:String(data.get('body')||'').trim(),created:date(),state:'Qaralama'} }
function saveMail(form){let m=mailFromForm(form);if(!m)return;state.mailLog.unshift({...m,id:uid()});log(`${applicant(m.applicantId).first} üçün məktub layihəsi saxlandı`);toast('Məktub layihəsi saxlandı');return m}
function emailExternal(form){let m=mailFromForm(form);if(!m)return;let link=`mailto:${encodeURIComponent(m.to)}?subject=${encodeURIComponent(m.subject)}&body=${encodeURIComponent(m.body+'\n\nGöndərən HR: '+m.from)}`;saveMail(form);location.href=link;toast('E-poçt tətbiqində layihə açılır; göndəriş təsdiqlənməyib.')}
function csvExport(){let lines=[['Namizəd','Email','Telefon','Vakansiya','Meyar','Status'],...state.applications.map(a=>[a.first+' '+a.last,a.email,a.phone,job(a.jobId)?.title||'',`${evaluate(a,job(a.jobId)).yes}/${evaluate(a,job(a.jobId)).total}`,statusLabel(a.status)])];let str='\ufeff'+lines.map(r=>r.map(x=>'"'+String(x).replace(/^[=+@\-]/,'\'$&').replaceAll('"','""')+'"').join(',')).join('\r\n');let blob=new Blob([str],{type:'text/csv;charset=utf-8'});let u=URL.createObjectURL(blob);let a=document.createElement('a');a.href=u;a.download='hireflow-applications.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);toast('CSV faylı hazırlanıb')}
function downloadData(id,kind){let a=applicant(id);let data=kind==='cv'?a?.cvData:a?.certData,name=kind==='cv'?a?.cvName:a?.certName;if(!data)return toast('Bu fayl demo yaddaşında saxlanılmayıb.');let anchor=document.createElement('a');anchor.href=data;anchor.download=name;anchor.click()}
function handleAction(e){let a=e.target.closest('[data-action]');if(!a)return;let type=a.dataset.action,id=a.dataset.id;e.preventDefault();if(type==='mobile'){mobileMenu=!mobileMenu;return render()}if(type==='logout'){adminLogged=false;sessionStorage.removeItem(SESSION);return navigate('/admin')}if(type==='demo-login'){adminLogged=true;sessionStorage.setItem(SESSION,'yes');return navigate('/admin/dashboard')}if(type==='toggle-job'){let j=job(id);j.status=j.status==='active'?'inactive':'active';log(`${j.title} vakansiyasının statusu: ${j.status}`);return render()}if(type==='edit-job'){editingJob=id;editor=[];return navigate('/admin/new')}if(type==='add-criterion'){editor.push({id:uid(),name:'',keywords:'',required:false});document.getElementById('criteria-list').innerHTML=criteriaEditor();return}if(type==='remove-criterion'){if(editor.length===1)return toast('Ən azı bir meyar olmalıdır.');editor.splice(+a.dataset.index,1);document.getElementById('criteria-list').innerHTML=criteriaEditor();return}if(type==='open-requests'){activeJob=id;applicantGroup='all';return navigate('/admin/requests/'+id)}if(type==='switch-group'){applicantGroup=a.dataset.group;return render()}if(type==='open-applicant'){activeApplicant=id;return navigate('/admin/applicant/'+id)}if(type==='back-requests'){return navigate(activeJob?'/admin/requests/'+activeJob:'/admin/requests')}if(type==='compose'){modal=composeModal(id);return render()}if(type==='close-modal'){modal=null;return render()}if(type==='open-email'){let form=document.getElementById('mail-form');if(form&&form.reportValidity())emailExternal(form);return}if(type==='mark-replied'){let p=applicant(id);p.replyStatus='recorded';log(`${p.first} ${p.last} — e-poçt göndərilməsi HR tərəfindən qeydə alındı`);modal=null;toast('Geri dönüş qeydə alındı (manual)');return render()}if(type==='download-file'){return downloadData(id,a.dataset.kind)}if(type==='reply-contact'){let m=state.messages.find(x=>x.id===id);if(!m)return;location.href=`mailto:${encodeURIComponent(m.email)}?subject=${encodeURIComponent('HireFlow — müraciətinizə cavab')}&body=${encodeURIComponent('Salam '+m.first+',\n\n')}`;return}if(type==='mark-contact'){let m=state.messages.find(x=>x.id===id);m.status='answered';log(`${m.first} ${m.last} — əlaqə cavabı qeyd olundu`);return render()}if(type==='edit-faq'){modal=faqModal(id);return render()}if(type==='delete-faq'){if(!confirm('Bu FAQ silinsin?'))return;state.faqs=state.faqs.filter(f=>f.id!==id);log('FAQ silindi');return render()}if(type==='seed-hundred'){let j=job(id);if(!j)return;const words=['Python, PostgreSQL, IELTS 7.0, Bakı','Python, SQL, Bakı','SQL, IELTS B2','JavaScript, HTML, CSS','Python, FastAPI','Excel, HR','Python, MySQL, Bakı','Django, IELTS 6.5','React, SQL','Git, Linux'];for(let n=0;n<100;n++){let i=n+1,sk=words[n%words.length];state.applications.push({id:uid(),jobId:j.id,first:'Namizəd',last:String(i).padStart(3,'0'),father:'Demo',email:'demo'+i+'.'+j.id+'@example.com',phone:'+994 00 000 00 00',city:n%3?'Bakı':'Gəncə',skills:sk,motivation:'Sintetik müraciət: tədris və texnoloji inkişaf sahəsində çalışmaq istəyirəm.',github:'',linkedin:'',cvText:sk+' üzrə nümunə CV məzmunu',cvName:'synthetic-'+i+'.txt',cvData:'',certName:'',certData:'',status:'new',response:'',replyStatus:'none',created:date(),logs:[]})}log(j.title+' üçün 100 sintetik namizəd yaradıldı');toast('100 sintetik namizəd əlavə edildi');return render()}if(type==='export'){return csvExport()}}
async function handleSubmit(e){let form=e.target;if(!form.id)return;e.preventDefault();if(form.id==='application-form')return await submitApplication(form);if(form.id==='bulk-cv'){let files=Array.from(form.querySelector('[name=bulkFiles]').files||[]);if(!files.length)return toast('Ən azı bir CV seçin.');if(files.length>100)return toast('Bir dəfəyə maksimum 100 CV idxal edin.');let j=job(form.dataset.id),count=0;let btn=form.querySelector('button[type=submit]');btn.disabled=true;try{for(let file of files){if(file.size>4*1024*1024||!/\.(pdf|docx|txt)$/i.test(file.name))continue;let text='';try{text=await extractCV(file)}catch(err){}let name=file.name.replace(/\.[^.]+$/,'').replace(/[_-]+/g,' ').trim().split(/\s+/);let entry={id:uid(),jobId:j.id,first:name[0]||'Namizəd',last:name.slice(1).join(' ')||'Yoxlanmalı',father:'',email:'',phone:'',city:'',skills:'',motivation:'Toplu CV idxalı — məlumatları HR təsdiqləməlidir.',github:'',linkedin:'',cvText:text.slice(0,90000),cvName:file.name,cvData:await fileData(file,250000),certName:'',certData:'',status:'review',response:'',replyStatus:'none',created:date(),logs:[]};state.applications.push(entry);count++}if(!save()){state.applications.splice(-count,count);return}log(j.title+' üçün '+count+' CV toplu idxal edildi');toast(count+' CV idxal edildi');return render()}finally{btn.disabled=false}return;}if(form.id==='contact-form'){let x=new FormData(form);let m={id:uid(),first:x.get('first').trim(),last:x.get('last').trim(),email:x.get('email').trim(),phone:x.get('phone').trim(),message:x.get('message').trim(),created:date(),status:'new'};state.messages.push(m);if(!save()){state.messages.pop();return}log(`${m.first} ${m.last} əlaqə sorğusu göndərdi`);form.reset();return toast('Mesaj bu brauzerin demo yaddaşına əlavə edildi.')}if(form.id==='login-form'){let x=new FormData(form);if(x.get('email')==='admin@hireflow.local'&&x.get('password')==='demo123'){adminLogged=true;sessionStorage.setItem(SESSION,'yes');navigate('/admin/dashboard')}else toast('Demo giriş məlumatları düzgün deyil. Demo düyməsindən istifadə edin.');return}if(form.id==='job-editor'){let x=new FormData(form);let criteria=editor.map(c=>({id:c.id,name:c.name.trim(),keywords:c.keywords.trim(),required:!!c.required})).filter(c=>c.name);if(!criteria.length)return toast('Ən azı bir meyar daxil edin.');let id=form.dataset.id||uid(),prior=job(id),j={id,title:x.get('title').trim(),company:x.get('company').trim(),location:x.get('location').trim(),type:x.get('type'),description:x.get('description').trim(),responsibilities:x.get('responsibilities').trim(),criteria,github:x.has('github'),linkedin:x.has('linkedin'),status:x.has('active')?'active':'inactive',views:prior?.views||0,created:prior?.created||date()};if(prior)Object.assign(prior,j);else state.jobs.unshift(j);log(`${j.title} vakansiyası ${prior?'yeniləndi':'yaradıldı'}`);editingJob=null;editor=[];toast('Vakansiya saxlanıldı');return navigate('/admin/vacancies')}if(form.id==='candidate-reply'){let a=applicant(form.dataset.id),x=new FormData(form),reply=x.get('reply').trim();a.response+=(a.response?'\n':'')+reply;a.cvText+='\nNamizədin əlavə cavabı (HR daxil edib): '+reply;log(`${a.first} ${a.last} üçün əlavə məlumat qeydə alındı`);toast('Yeni məlumat əlavə edildi; meyarlar yenidən hesablandı');return render()}if(form.id==='faq-form'){let x=new FormData(form);state.faqs.push({id:uid(),q:x.get('question').trim(),a:x.get('answer').trim()});log('FAQ əlavə edildi');toast('Sual əlavə edildi');return render()}if(form.id==='edit-faq-form'){let x=new FormData(form),f=state.faqs.find(x=>x.id===form.dataset.id);f.q=x.get('q').trim();f.a=x.get('a').trim();modal=null;log('FAQ yeniləndi');return render()}if(form.id==='mail-form'){saveMail(form);modal=null;return render()}}
function handleChange(e){let el=e.target;if(el.matches('#candidate-status'))return changeStatus(el.dataset.id,el.value);if(el.dataset.criterion){let c=editor[+el.dataset.index];if(c)c[el.dataset.criterion]=el.type==='checkbox'?el.checked:el.value}if(el.matches('#mail-kind')){const fields=document.getElementById('meeting-fields'),form=document.getElementById('mail-form'),a=applicant(form?.dataset.id),j=job(a?.jobId);if(!form||!a)return;fields.classList.toggle('hide',el.value!=='interview');form.elements.subject.value=el.value==='interview'?`${j.title} — müsahibəyə dəvət`:`${j.title} — müraciətiniz barədə`;updateMeetingMessage()}}
function updateMeetingMessage(){const f=document.getElementById('mail-form');if(!f||document.getElementById('mail-kind')?.value!=='interview')return;let a=applicant(f.dataset.id),j=job(a.jobId),t=document.getElementById('meeting-time').value,l=document.getElementById('meeting-location').value;f.elements.body.value=`Hörmətli ${a.first} ${a.last},\n\n${j.title} vakansiyasına müraciətinizə görə təşəkkür edirik. Sizi müsahibəyə dəvət etmək istərdik.\n\nGörüş vaxtı: ${t?new Date(t).toLocaleString('az-AZ'):'HR tərəfindən təsdiqlənəcək'}\nGörüş yeri / keçid: ${l||'Əlavə məlumat veriləcək'}\n\nİştirakınızı bu e-poçta cavab verməklə təsdiqləyə bilərsiniz.\n\nHörmətlə,\n${j.company} HR komandası`}
document.addEventListener('click',e=>{const r=e.target.closest('[data-route]');if(r){e.preventDefault();navigate(r.dataset.route);return}const a=e.target.closest('[data-admin]');if(a){e.preventDefault();routeAdmin(a.dataset.admin);return}if(e.target.classList.contains('modal-back')){modal=null;render();return}handleAction(e)});document.addEventListener('submit',handleSubmit);document.addEventListener('change',handleChange);document.addEventListener('input',e=>{if(e.target.matches('#job-search')){searchValue=e.target.value;updateJobResults()}if(e.target.matches('#job-type'))updateJobResults();if(e.target.dataset.criterion&&!['checkbox'].includes(e.target.type))handleChange(e);if(e.target.matches('#meeting-time,#meeting-location'))updateMeetingMessage()});window.addEventListener('popstate',render);window.addEventListener('hashchange',()=>{if(isFile||location.hash.startsWith('#/'))render()});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;render()}});
if(isFile&&location.hash==='#')location.hash='#/';save();render();
})();
